variables.query:
{
  orders(query: "created_at:>='2026-09-06T08:00:00Z'") {
    edges {
      node {
        id
        name
        createdAt
        updatedAt
        test
        cancelledAt
        cancelReason
        paymentGatewayNames
        totalPriceSet {
          shopMoney {
            amount
          }
        }
        currentTotalPriceSet {
          shopMoney {
            amount
          }
        }
        totalShippingPriceSet {
          shopMoney {
            amount
          }
        }
        discountCodes
        discountApplications {
          edges {
            node {
              __typename
              targetType
              ... on DiscountCodeApplication {
                code
              }
            }
          }
        }
        note
        phone
        tags
        customAttributes {
          key
          value
        }
        customer {
          id
          defaultPhoneNumber {
            phoneNumber
          }
          phone
        }
        shippingAddress {
          name
          phone
          address1
          address2
          city
          province
        }
        customerJourneySummary {
          firstVisit {
            landingPage
            referrerUrl
            utmParameters {
              source
              medium
              campaign
              content
            }
          }
          lastVisit {
            landingPage
            referrerUrl
            utmParameters {
              source
              medium
              campaign
              content
            }
          }
        }
        lineItems {
          edges {
            node {
              id
              title
              variantTitle
              currentQuantity
              unfulfilledQuantity
              variant {
                id
              }
              originalUnitPriceSet {
                shopMoney {
                  amount
                }
              }
              discountAllocations {
                allocatedAmountSet {
                  shopMoney {
                    amount
                  }
                }
              }
              taxLines(first: 4) {
                rate
                ratePercentage
              }
            }
          }
        }
        fulfillments(first: 10) {
          id
          status
          createdAt
        }
        transactions(first: 30) {
          id
          kind
          status
          gateway
          amountSet {
            shopMoney {
              amount
            }
          }
        }
      }
    }
  }
}
